const panNames={assets:['Asset Stage','P0'],draw:['Drawing Desk / Ink & Paint','P0 + P1'],camera:['Shot & Camera','P0'],sound:['Sound Desk','P0'],pose:['Pose & Timing','P1'],fx:['Matte & FX','P1'],patch:['Patch Track','P1'],layout:['Space Layout','P2'],export:['Render & QA','P1']};
function notify(message,error=false){$('status').textContent=message;$('toast').textContent=message;$('toast').className='show'+(error?' error':'');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('show'),4300);}
function on(id,fn){const e=$(id);if(e)e.onclick=()=>Promise.resolve().then(fn).catch(e=>notify(e.message,true));}
function changed(id,fn){const e=$(id);if(e)e.onchange=()=>Promise.resolve().then(fn).catch(e=>notify(e.message,true));}
function safe(fn){return(...a)=>Promise.resolve().then(()=>fn(...a)).catch(e=>notify(e.message,true));}
const value=id=>$(id)?.value,num=id=>Number(value(id)),checked=id=>!!$(id)?.checked;
function field(id,label,v,type='number',attrs=''){return `<label class="field">${label}<input id="${id}" type="${type}" value="${escape(v)}" ${attrs}></label>`;}
function select(id,label,options,v){return `<label class="field">${label}<select id="${id}">${options.map(o=>{const a=Array.isArray(o)?o:[o,o];return `<option value="${escape(a[0])}" ${String(a[0])===String(v)?'selected':''}>${escape(a[1])}</option>`;}).join('')}</select></label>`;}
function button(id,label,cls='wide'){return `<button id="${id}" class="${cls}">${label}</button>`;}
const divide='<div class="divider"></div>',help=s=>`<p class="help">${s}</p>`;
function save(blob,name){M.download(blob,name);}
function saveJSON(obj,name){save(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),name);}
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Koma-Token':window.KOMA_TOKEN,...(window.KOMA_EDIT_LEASE?{'X-Koma-Lease':window.KOMA_EDIT_LEASE}:{})},body:body?JSON.stringify(body):undefined});const j=await r.json();if(!r.ok)throw Error(j.error||'Local request failed');return j;}
function snapshot(){return isServer?api('snapshot'):Promise.resolve(V.snapshot(local));}
async function saveLocal(s){if(storage!=='indexeddb'||demoOnly)return;const snap=V.snapshot(s);await new Promise((resolve,reject)=>{const tx=db.transaction('sessions','readwrite'),st=tx.objectStore('sessions'),r=st.get('current');r.onsuccess=()=>{if(r.result)st.put(r.result,'previous');st.put(snap,'current');};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Save aborted'));});}
function enqueue(fn){const next=queue.then(fn);queue=next.catch(()=>{});return next;}
function receive(s){state=s;frame=Math.min(frame,state.project.frames-1);proposal=null;$('agentCommit').disabled=true;renderAll();}
async function withLease(fn){if(!isServer||window.KOMA_EDIT_LEASE)return fn();const lease=await api('edit-lease/acquire',{owner:'Human browser',purpose:'atomic UI edit',seconds:45});window.KOMA_EDIT_LEASE=lease.lease;try{return await fn();}finally{try{await api('edit-lease/release',{lease:lease.lease});}finally{window.KOMA_EDIT_LEASE=null;}}}
function act(commands,expectedRevision){return enqueue(()=>withLease(async()=>{stop();const revision=expectedRevision??state.revision;if(isServer)receive(await api('command',{commands,expectedRevision:revision}));else{const draft=V.restore(V.snapshot(local));draft.apply(commands,revision);await saveLocal(draft);local=draft;receive(local.state());}return state;}));}
function previewCommands(commands,scope=null){return enqueue(async()=>{if(isServer)return api('preview',{commands,expectedRevision:state.revision,scope});const draft=V.restore(V.snapshot(local)),plan=draft.preview(commands,draft.revision,scope);await saveLocal(draft);local=draft;return plan;});}
function commitProposal(plan){return enqueue(()=>withLease(async()=>{if(isServer)receive(await api('commit',{planId:plan.id,expectedRevision:plan.baseRevision}));else{const draft=V.restore(V.snapshot(local));draft.commit(plan.id,plan.baseRevision);await saveLocal(draft);local=draft;receive(draft.state());}return state;}));}

function loadProject(p){return enqueue(async()=>{stop();C.validate(p);if(isServer)receive(await api('load',{project:p,expectedRevision:state.revision}));else{const d=V.restore(V.snapshot(local));d.load(p,d.revision);await saveLocal(d);local=d;receive(d.state());}frame=0;selected=p.production?.shots[0]?.layers.find(l=>!l.locked)?.id||null;view='composite';tool='select';renderAll();setView('composite');setTool('select');});}
async function history(direction){return enqueue(async()=>{stop();if(isServer)receive(await api(direction,{expectedRevision:state.revision}));else{const d=V.restore(V.snapshot(local));d[direction](d.revision);await saveLocal(d);local=d;receive(d.state());}});}
function current(){return state.project.production?P.locate(state.project,frame):null;}
function layer(){return current()?.shot.layers.find(l=>l.id===selected)||null;}
function asset(){const l=layer();return l?state.project.production.assets.find(a=>a.id===P.displayCel(current().shot,l,current().local)):null;}
function id(prefix){let x;const pool=JSON.stringify(state.project);do{x=prefix+'_'+Math.random().toString(36).slice(2,9);}while(pool.includes('"'+x+'"'));return x;}
function shotCommand(op,more={}){return{op,shot:current().shot.id,...more};}
