function renderAll(){if(!state.project.production){renderLegacy();return;}const p=state.project,at=current();if(!layer())selected=at.shot.layers.find(l=>!l.locked&&l.asset)?.id||at.shot.layers[0]?.id||null;$('projectName').textContent=p.name;$('storage').textContent=isServer?'LOCAL SERVER':demoOnly?'DEMO / UNSAVED':storage==='indexeddb'?'LOCAL VAULT':'SESSION ONLY';$('storage').style.color=storage==='session'&&!isServer?'#d7b484':'';$('revision').textContent='r'+state.revision;$('undo').disabled=!state.canUndo;$('redo').disabled=!state.canRedo;$('canvasSize').textContent=p.width+' x '+p.height;$('stageWrap').style.aspectRatio=p.width+'/'+p.height;$('overlay').width=p.width;$('overlay').height=p.height;$('scrubber').max=p.frames-1;$('duration').textContent='/ '+(p.frames/p.fps).toFixed(2)+'s / '+p.fps+' fps';$('metrics').textContent=p.production.assets.length+' assets / '+p.production.shots.length+' shots';renderLists();renderInspector();paint();lastShot=at.shot.id;fitStage();}
function renderLegacy(){const p=state.project;$('projectName').textContent=p.name;$('stage').innerHTML=C.renderSVG(p,frame);$('inspector').innerHTML='<h3>Legacy project preserved</h3>'+help('This project uses the earlier cat/cinema schema. Open legacy.html for its original controls. Loading a production demo creates a reversible import, not a silent migration.')+button('loadDemo','Load production demo');on('loadDemo',()=>loadProject(KomaProductionDemo.make()));$('shots').innerHTML='';$('layers').innerHTML='';$('assets').innerHTML='';}
function paint(){if(!state.project.production)return;const at=current(),p=state.project;$('stage').innerHTML=P.renderSVG(p,frame,{mode:view,guides:checked('guides')});let ghost='';if(checked('onion')&&layer()&&view!=='layout'){for(const offset of [-Math.max(1,layer().hold),Math.max(1,layer().hold)])if(at.local+offset>=0&&at.local+offset<at.shot.duration)ghost+=P.renderSVG(p,frame+offset,{onlyLayer:selected,transparent:true,noPatches:true,mode:'base'});}$('ghost').innerHTML=ghost;$('frameLabel').textContent='F '+String(frame).padStart(4,'0')+' / LOCAL '+String(Math.floor(at.local)).padStart(3,'0');$('frameOutput').textContent=frame;$('scrubber').value=frame;$('timecode').textContent=String(Math.floor(frame/p.fps/60)).padStart(2,'0')+':'+String(Math.floor(frame/p.fps)%60).padStart(2,'0')+':'+String(frame%p.fps).padStart(2,'0');$('shotLabel').textContent='SHOT '+(p.production.shots.indexOf(at.shot)+1)+' / '+at.shot.duration+' FRAMES';$('shotName').textContent=at.shot.name;$('selectionInfo').textContent=layer()?layer().name+' / '+(asset()?.name||'Group'):'No layer selected';document.querySelectorAll('.playhead').forEach(e=>e.style.left=(frame/(p.frames-1)*100)+'%');drawOverlay();}
function schedulePaint(){if(!rafPaint)rafPaint=requestAnimationFrame(()=>{rafPaint=0;paint();});}
function seek(f,remote=false){if(!state.project.production)return;frame=Math.max(0,Math.min(state.project.frames-1,Math.floor(f)));const change=current().shot.id!==lastShot;if(change){selected=current().shot.layers.find(l=>l.id===selected)?.id||current().shot.layers.find(l=>!l.locked&&l.asset)?.id||null;lastShot=current().shot.id;renderLists();}if(change||!playing)renderInspector();paint();if(isServer&&!remote&&!playing)api('view',{frame}).catch(()=>{});}
function renderLists(){const p=state.project,q=p.production,at=current();let start=0;$('shots').innerHTML=q.shots.map((s,i)=>{const o=`<div class="shot ${s.id===at.shot.id?'active':''}" draggable="true" data-shot="${s.id}" data-start="${start}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><strong>${escape(s.name.replace(/^\d+\s*\/\s*/,''))}</strong><small>${s.duration}f &middot; ${(s.duration/p.fps).toFixed(2)}s</small></div></div>`;start+=s.duration;return o;}).join('');document.querySelectorAll('[data-shot]').forEach(e=>{e.onclick=()=>{stop();seek(Number(e.dataset.start));renderLists();};e.ondragstart=ev=>ev.dataTransfer.setData('text/plain',e.dataset.shot);e.ondragover=ev=>ev.preventDefault();e.ondrop=safe(ev=>{ev.preventDefault();const id=ev.dataTransfer.getData('text/plain'),order=q.shots.map(s=>s.id);const old=order.indexOf(id);if(old<0)return;order.splice(old,1);order.splice(order.indexOf(e.dataset.shot),0,id);return act([{op:'prod_shot_order',order}]);});});
 $('layers').innerHTML=[...at.shot.layers].reverse().map(l=>`<div class="layer ${l.id===selected?'active':''}" data-layer-select="${l.id}"><button data-visible="${l.id}" title="Visibility">${l.visible?'&#9673;':'&#9675;'}</button><span style="padding-left:${l.parent?10:0}px">${l.parent?'&#8627; ':''}${escape(l.name)}</span><small>${l.asset?'CEL':'GRP'}</small><button data-lock="${l.id}" title="Direct edit protection">${l.locked?'&#9632;':'&#9633;'}</button></div>`).join('');document.querySelectorAll('[data-layer-select]').forEach(e=>e.onclick=ev=>{if(ev.target.closest('button'))return;selected=e.dataset.layerSelect;renderLists();renderInspector();paint();});document.querySelectorAll('[data-visible]').forEach(e=>e.onclick=safe(()=>act([shotCommand('prod_layer_set',{layer:e.dataset.visible,property:'visible',value:!P.findLayer(at.shot,e.dataset.visible).visible})])));document.querySelectorAll('[data-lock]').forEach(e=>e.onclick=safe(()=>act([shotCommand('prod_layer_set',{layer:e.dataset.lock,property:'locked',value:!P.findLayer(at.shot,e.dataset.lock).locked})])));
 const palette=new Map(q.palette.map(c=>[c.id,c.color]));$('assets').innerHTML=q.assets.map(a=>`<div class="asset" data-asset="${a.id}"><svg viewBox="0 0 ${a.width||100} ${a.height||100}">${a.kind==='drawing'?P.drawingSVG(a,palette,'thumb-'+a.id):a.kind==='raster'?`<image href="${a.data}" width="${a.width}" height="${a.height}"/>`:'<path d="M20 30L50 10L80 30V70L50 90L20 70Z M20 30L50 50L80 30 M50 50V90" fill="none" stroke="#88dbc5" stroke-width="2"/>'}</svg><b>${escape(a.name)}</b><small>${a.kind.toUpperCase()} / ${a.width||a.mesh.vertices.length}${a.height?' x '+a.height:' vertices'}</small></div>`).join('');$('assetCount').textContent=q.assets.length;document.querySelectorAll('[data-asset]').forEach(e=>e.onclick=safe(async()=>{const a=P.findAsset(p,e.dataset.asset);if(a.kind==='mesh'){showTab('layout');return;}const l=P.newLayer(id('layer'),a.id,a.name);await act([shotCommand('prod_layer_add',{value:l})]);selected=l.id;renderAll();}));renderTracks();}
function renderTracks(){const p=state.project,at=current();let list=at.shot.layers.filter(l=>!l.guide).map(l=>{const changes=[{frame:0,asset:l.asset},...l.exposure.filter(e=>e.frame>0)],spans=changes.map((e,i)=>{const end=changes[i+1]?.frame??at.shot.duration;return e.asset===null?'':`<i class="span" style="left:${(at.start+e.frame)/p.frames*100}%;width:${(end-e.frame)/p.frames*100}%"></i>`;}).join(''),keys=l.keys.map(k=>`<i class="key" style="left:${(at.start+k.frame)/p.frames*100}%"></i>`).join('');return `<div class="track ${l.id===selected?'selected':''}" data-track-select="${l.id}"><span class="track-name">${escape(l.name)}</span><div class="track-line">${spans}${keys}<i class="playhead" style="left:${frame/(p.frames-1)*100}%"></i></div></div>`;}).join('');for(const t of p.production.audio){const start=(t.shot?A.shotStart(p,t.shot):0)+t.start;list+=`<div class="track"><span class="track-name">&#9835; ${escape(t.name)}</span><div class="track-line"><div style="position:absolute;left:${start/p.frames*100}%;width:${t.length/p.frames*100}%;height:100%">${wave(t.peaks,t.mute?'#586877':'#aa936f')}</div><i class="playhead" style="left:${frame/(p.frames-1)*100}%"></i></div></div>`;}$('tracks').innerHTML=list;document.querySelectorAll('.track-line').forEach(e=>e.onclick=ev=>{stop();const r=e.getBoundingClientRect();seek((ev.clientX-r.left)/r.width*p.frames);});document.querySelectorAll('[data-track-select] .track-name').forEach(e=>e.onclick=()=>{selected=e.parentElement.dataset.trackSelect;renderLists();renderInspector();paint();});}
function wave(peaks,color='#8dd1bd'){const points=peaks.map((v,i)=>`M${i*2} ${16-v*16}v${Math.max(.5,v*32)}`).join('');return `<svg viewBox="0 0 ${peaks.length*2} 32" preserveAspectRatio="none"><path d="${points}" stroke="${color}" stroke-width="1.5"/></svg>`;}
function showTab(t){tab=t;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));renderInspector();}
